out1 = os.path.join(T, 'single_new.dxf')
r = subprocess.run([sys.executable, '-X', 'utf8', os.path.join(T, 'merge_single.py'), pdir1, '26-072721', out1, '--template', tpl], capture_output=True, text=True)
